// Safely read input regardless of whether execution started from Manual Trigger or Webhook
let inputJson = {};
try {
  inputJson = $input.first() ? $input.first().json : {};
} catch(e) {}
const webhookBody = inputJson.body || inputJson || {};

// Default settings (Override these or pass via GitHub Webhook)
const DEFAULT_OWNER  = 'jjms95';
const DEFAULT_REPO   = 'n8n-commerce-flows';
const DEFAULT_BRANCH = 'main';
const N8N_BASE_URL   = 'http://127.0.0.1:5678'; // Or internal n8n URL
const AUTO_ACTIVATE  = false; // User controls activation manually

let repoOwner  = DEFAULT_OWNER;
let repoName   = DEFAULT_REPO;
let branchName = DEFAULT_BRANCH;

if (webhookBody.repository) {
  repoName = webhookBody.repository.name || DEFAULT_REPO;
  repoOwner = (webhookBody.repository.owner && webhookBody.repository.owner.login) ? webhookBody.repository.owner.login : DEFAULT_OWNER;
  if (webhookBody.ref) {
    branchName = webhookBody.ref.replace('refs/heads/', '');
  }
}

return {
  repo_owner: repoOwner,
  repo_name: repoName,
  branch: branchName,
  n8n_base_url: N8N_BASE_URL,
  auto_activate: AUTO_ACTIVATE,
  sync_source: webhookBody.repository ? 'github_push_webhook' : 'manual_execution'
};

const cfg = $('Code - Initialize Sync Configuration').item.json;
const treeData = $input.item.json.tree || [];

// Filter only workflow JSON files (root or subfolders, excluding package/config files)
const workflowFiles = treeData.filter(item => {
  if (item.type !== 'blob') return false;
  const path = item.path.toLowerCase();
  if (!path.endsWith('.json')) return false;
  if (path.includes('package') || path.includes('tsconfig') || path.includes('mcp_config') || path.includes('hooks.json') || path.includes('n8n_git_sync')) return false;
  return true;
});

if (workflowFiles.length === 0) {
  return [];
}

return workflowFiles.map(file => ({
  file_path: file.path,
  file_sha: file.sha,
  raw_url: `https://raw.githubusercontent.com/${cfg.repo_owner}/${cfg.repo_name}/${cfg.branch}/${file.path}`,
  config: cfg
}));

const downloadedItems = $input.all();
const fileMetaItems = $('Code - Filter Workflow JSON Files').all();
const existingRes = $('HTTP - List Existing N8N Workflows').first()?.json?.data || [];

// Build lookup map for existing N8N workflows by name, id, and common flow slugs
const wfLookup = {};
existingRes.forEach(w => {
  if (w.name) {
    wfLookup[w.name.trim()] = w.id;
    const lower = w.name.toLowerCase();
    if (lower.includes('flow 0') || lower.includes('orchestrator')) wfLookup['flow0_whatsapp_orchestrator'] = w.id;
    if (lower.includes('flow 1') || lower.includes('sales')) wfLookup['flow1_sales_state_machine'] = w.id;
    if (lower.includes('flow 2') || lower.includes('catalog') || lower.includes('crud')) wfLookup['flow2_product_catalog_crud'] = w.id;
    if (lower.includes('flow 3') || lower.includes('report')) wfLookup['flow3_automated_reports'] = w.id;
    if (lower.includes('flow 4') || lower.includes('appointment') || lower.includes('booking')) wfLookup['flow4_appointment_booking'] = w.id;
  }
  if (w.id) wfLookup[w.id] = w.id;
});

// Pair and sort items so subflows (Flows 1-4) are processed BEFORE Master Orchestrator (Flow 0)
const paired = downloadedItems.map((item, idx) => ({
  downloaded: item.json || {},
  meta: fileMetaItems[idx]?.json || {}
}));

paired.sort((a, b) => {
  const pA = (a.meta.file_path || '').toLowerCase();
  const pB = (b.meta.file_path || '').toLowerCase();
  if (pA.includes('flow0')) return 1;
  if (pB.includes('flow0')) return -1;
  return 0;
});

const results = [];

for (const { downloaded, meta } of paired) {
  let rawContent = downloaded.data !== undefined ? downloaded.data : (downloaded.body !== undefined ? downloaded.body : downloaded);
  let parsedWorkflow = rawContent;

  if (typeof rawContent === 'string') {
    try { parsedWorkflow = JSON.parse(rawContent); } catch(e) { parsedWorkflow = null; }
  }

  if (!parsedWorkflow || !parsedWorkflow.nodes || !Array.isArray(parsedWorkflow.nodes)) {
    results.push({
      valid: false,
      file_path: meta.file_path || 'unknown.json',
      error: 'File does not contain a valid n8n workflow structure'
    });
    continue;
  }

  const workflowName = parsedWorkflow.name || meta.file_path.replace('.json', '');
  const existingWf = existingRes.find(w => w.name && (w.name.trim() === workflowName.trim() || w.name.trim() === parsedWorkflow.name?.trim()));

  // Resolve and replace dynamic subflow IDs in Execute Workflow nodes
  const resolvedNodes = parsedWorkflow.nodes.map(n => {
    const clone = { ...n };
    if (clone.type && clone.type.includes('executeWorkflow') && clone.parameters && clone.parameters.workflowId) {
      const targetSlug = typeof clone.parameters.workflowId === 'object' ? clone.parameters.workflowId.value : clone.parameters.workflowId;
      if (wfLookup[targetSlug]) {
        clone.parameters = {
          ...clone.parameters,
          workflowId: wfLookup[targetSlug]
        };
      }
    }
    return clone;
  });

  results.push({
    valid: true,
    action: existingWf ? 'UPDATE' : 'CREATE',
    existing_id: existingWf ? existingWf.id : null,
    workflow_name: workflowName,
    file_path: meta.file_path,
    nodes: resolvedNodes,
    connections: parsedWorkflow.connections || {},
    settings: parsedWorkflow.settings || { executionOrder: 'v1' },
    tags: parsedWorkflow.tags || [],
    auto_activate: meta.config ? meta.config.auto_activate : false
  });
}

return results;

const items = $input.all().map(i => i.json);
const cfg = $('Code - Initialize Sync Configuration').item.json;

return {
  status: 'completed',
  repo: `${cfg.repo_owner}/${cfg.repo_name}`,
  branch: cfg.branch,
  synchronized_workflows_count: items.length,
  workflows: items.map(w => ({
    name: w.name || w.workflow_name,
    id: w.id || w.existing_id,
    active: w.active || false
  })),
  published_policy: 'Unpublished by default (manual user activation required)',
  sync_timestamp: new Date().toISOString()
};
